package streamix.readingcatalog
import org.jsoup.Jsoup
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlinx.coroutines.runBlocking
class FinalProviderAdapterCoverageTest {
 @Test fun mangaHubUsesItsReaderImages()=runBlocking{val p=MangaHubReadingRuntimeProvider{u->Jsoup.parse("""<div class="reader-image"><img src="/p.jpg"></div>""",u)};val e=ReadingCatalogEntry("m",ReadingKind.MANGA,"M","https://mangahub.ru/title/title",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","mangahub","https://mangahub.ru/title/title/chapter/1")));assertEquals(listOf("https://mangahub.ru/p.jpg"),p.chapter(e,c)?.pageUrls)}
 @Test fun mangaReaderUsesPageBreakImages()=runBlocking{val p=MangaReaderReadingRuntimeProvider{u->Jsoup.parse("""<div class="page-break"><img src="/p.jpg"></div>""",u)};val e=ReadingCatalogEntry("m",ReadingKind.MANGA,"M","https://mangareader.site/title",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","mangareader","https://mangareader.site/chapter/1")));assertEquals(listOf("https://mangareader.site/p.jpg"),p.chapter(e,c)?.pageUrls)}
 @Test fun mangaReaderFallsBackToDataOriginal()=runBlocking{val p=MangaReaderReadingRuntimeProvider{u->Jsoup.parse("""<div class="page-break"><img data-original="/original.jpg" src="data:image/gif;base64,placeholder"></div>""",u)};val e=ReadingCatalogEntry("m",ReadingKind.MANGA,"M","https://mangareader.site/title",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","mangareader","https://mangareader.site/chapter/1")));assertEquals(listOf("https://mangareader.site/original.jpg"),p.chapter(e,c)?.pageUrls)}
 @Test fun mangaPlusExtractsOnlyPublicViewerImages()=runBlocking{val p=MangaPlusReadingRuntimeProvider{u->Jsoup.parse("""<div class="viewer-container"><img src="https://cdn.mangaplus.shueisha.co.jp/p.jpg"></div>""",u)};val e=ReadingCatalogEntry("m",ReadingKind.MANGA,"M","https://mangaplus.shueisha.co.jp/titles/1",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","mangaplus","https://mangaplus.shueisha.co.jp/viewer/1")));assertEquals(listOf("https://cdn.mangaplus.shueisha.co.jp/p.jpg"),p.chapter(e,c)?.pageUrls)}
 @Test fun vizExtractsPageImagesWhenPresent()=runBlocking{val p=VizReadingRuntimeProvider{u->Jsoup.parse("""<div class="chapter-page"><img src="https://cdn.viz.com/p.jpg"></div>""",u)};val e=ReadingCatalogEntry("m",ReadingKind.MANGA,"M","https://www.viz.com/manga/title",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","viz","https://www.viz.com/manga/title/chapters/1")));assertEquals(listOf("https://cdn.viz.com/p.jpg"),p.chapter(e,c)?.pageUrls)}
 @Test fun mangaUpExtractsViewerImagesWhenPublic()=runBlocking{val p=MangaUpReadingRuntimeProvider{u->Jsoup.parse("""<div class="viewer-page"><img src="https://global-img.manga-up.com/p.jpg"></div>""",u)};val e=ReadingCatalogEntry("m",ReadingKind.MANGA,"M","https://global.manga-up.com/manga/title",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","mangaup","https://global.manga-up.com/manga/title/chapter/1")));assertEquals(listOf("https://global-img.manga-up.com/p.jpg"),p.chapter(e,c)?.pageUrls)}
 @Test fun reaperScansUsesReaderArea()=runBlocking{val p=ReaperScansReadingRuntimeProvider{u->Jsoup.parse("""<div id="readerarea"><img data-src="/p.jpg"></div>""",u)};val e=ReadingCatalogEntry("m",ReadingKind.MANHWA,"M","https://reaperscans.com/series/title",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","reaper-scans","https://reaperscans.com/series/title/chapter/1")));assertEquals(listOf("https://reaperscans.com/p.jpg"),p.chapter(e,c)?.pageUrls)}
 @Test fun reaperScansFallsBackToDataOriginal()=runBlocking{val p=ReaperScansReadingRuntimeProvider{u->Jsoup.parse("""<div id="readerarea"><img data-original="/original.jpg" src="data:image/gif;base64,placeholder"></div>""",u)};val e=ReadingCatalogEntry("m",ReadingKind.MANHWA,"M","https://reaperscans.com/series/title",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","reaper-scans","https://reaperscans.com/series/title/chapter/1")));assertEquals(listOf("https://reaperscans.com/original.jpg"),p.chapter(e,c)?.pageUrls)}
 @Test fun jNovelClubExtractsRenderedChapterText()=runBlocking{val p=JNovelClubReadingRuntimeProvider{u->Jsoup.parse("""<div class="chapter-content"><p>Public sample first paragraph.</p><p>Second paragraph stays separate.</p></div>""",u)};val e=ReadingCatalogEntry("n",ReadingKind.NOVEL,"N","https://j-novel.club/series/title",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","j-novel-club","https://j-novel.club/read/title/1")));assertEquals("Public sample first paragraph.\n\nSecond paragraph stays separate.",p.chapter(e,c)?.text)}

 @Test fun finalSiteAdaptersRejectCredentialAndNonstandardPortChapterUrlsBeforeFetching()=runBlocking{
  var fetchCalls=0
  val adapters=listOf(
   Triple(MangaHubReadingRuntimeProvider{fetchCalls++;Jsoup.parse("<img src='/p.jpg'>",it)},ReadingKind.MANGA,"https://mangahub.ru/title/t/chapter/1"),
   Triple(MangaReaderReadingRuntimeProvider{fetchCalls++;Jsoup.parse("<img src='/p.jpg'>",it)},ReadingKind.MANGA,"https://mangareader.site/chapter/1"),
   Triple(MangaPlusReadingRuntimeProvider{fetchCalls++;Jsoup.parse("<img src='https://cdn.mangaplus.shueisha.co.jp/p.jpg'>",it)},ReadingKind.MANGA,"https://mangaplus.shueisha.co.jp/viewer/1"),
   Triple(VizReadingRuntimeProvider{fetchCalls++;Jsoup.parse("<img src='https://cdn.viz.com/p.jpg'>",it)},ReadingKind.MANGA,"https://www.viz.com/manga/title/chapters/1"),
   Triple(MangaUpReadingRuntimeProvider{fetchCalls++;Jsoup.parse("<img src='https://global-img.manga-up.com/p.jpg'>",it)},ReadingKind.MANGA,"https://global.manga-up.com/manga/t/chapter/1"),
   Triple(ReaperScansReadingRuntimeProvider{fetchCalls++;Jsoup.parse("<img src='/p.jpg'>",it)},ReadingKind.MANHWA,"https://reaperscans.com/series/t/chapter/1"),
   Triple(JNovelClubReadingRuntimeProvider{fetchCalls++;Jsoup.parse("<div class='chapter-content'>sample</div>",it)},ReadingKind.NOVEL,"https://j-novel.club/read/t/1")
  )
  for((provider,kind,canonical) in adapters){
   val entry=ReadingCatalogEntry("entry",kind,"Title",canonical,ReadingEntryOrigin.MANUAL)
   for(unsafe in listOf(canonical.replace("https://","https://user@"),canonical.replace("https://","https://").replace(Regex("^(https://[^/]+)"),"$1:444"))){
    val chapter=ReadingChapterEntry("chapter","1",sources=listOf(ReadingChapterSource("source",provider.id,unsafe)))
    assertEquals(false,provider.supports(entry,chapter),provider.id+" accepted unsafe URL: "+unsafe)
    assertEquals(null,provider.chapter(entry,chapter),provider.id+" fetched unsafe URL: "+unsafe)
   }
  }
  assertEquals(0,fetchCalls)
 }


